<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();$q=trim($_GET['q']??'');if($q==='')json_response(['results'=>[]]);$res=[];if(can('students.view')){$s=db()->prepare('SELECT enrollment_no,label FROM (SELECT s.enrollment_no,u.name AS label FROM students s JOIN users u ON u.id=s.user_id) x WHERE enrollment_no LIKE ? OR label LIKE ? LIMIT 10');$s->execute(['%'.$q.'%','%'.$q.'%']);foreach($s as $r)$res[]=['type'=>'student','title'=>$r['enrollment_no'].' · '.$r['label'],'url'=>BASE_URL.'/admin/entity.php?e=students'];}json_response(['results'=>$res]);
